function ProfileEffectLayer({ effectId, size = 190, opacity = 1, style }) {
  const effect = profileEffectById(effectId);
  const progress = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    progress.stopAnimation();
    progress.setValue(0);
    if (!effect) return undefined;
    const loop = effect.adminSpecial === 'orbit'
      ? Animated.loop(Animated.timing(progress, { toValue: 1, duration: 4600, easing: Easing.linear, useNativeDriver: true }))
      : Animated.loop(Animated.sequence([
          Animated.timing(progress, { toValue: 1, duration: effect.animation === 'drift' ? 2600 : 1900, easing: Easing.inOut(Easing.sin), useNativeDriver: true }),
          Animated.timing(progress, { toValue: 0, duration: effect.animation === 'drift' ? 2600 : 1900, easing: Easing.inOut(Easing.sin), useNativeDriver: true }),
        ]));
    loop.start();
    return () => loop.stop();
  }, [effectId]);
  if (!effect) return null;
  const translateY = progress.interpolate({ inputRange: [0, 1], outputRange: [4, -5] });
  const scale = progress.interpolate({ inputRange: [0, 1], outputRange: effect.animation === 'pulse' ? [0.97, 1.06] : [0.99, 1.025] });
  const rotate = progress.interpolate({ inputRange: [0, 1], outputRange: effect.adminSpecial === 'orbit' ? ['0deg', '360deg'] : effect.animation === 'drift' ? ['-3deg', '3deg'] : ['-1deg', '1deg'] });
  const glow = progress.interpolate({ inputRange: [0, 1], outputRange: [0.68, 1] });
  if (effect.adminSpecial === 'orbit') return <Animated.View pointerEvents="none" style={[styles.profileEffectLayer, { width: size, height: size, opacity, transform: [{ rotate }] }, style]}><View style={[styles.adminOrbitRing, { width: size * .78, height: size * .78, borderRadius: size, borderColor: `${effect.color}88` }]} /><View style={[styles.adminOrbitDot, { backgroundColor: effect.color, top: size * .08, left: size * .47 }]} /><View style={[styles.adminOrbitDot, styles.adminOrbitDotSmall, { backgroundColor: '#FFFFFF', right: size * .08, top: size * .47 }]} /><View style={[styles.adminOrbitDot, styles.adminOrbitDotSmall, { backgroundColor: '#AF52DE', left: size * .12, bottom: size * .24 }]} /></Animated.View>;
  if (effect.adminSpecial === 'crown') return <Animated.View pointerEvents="none" style={[styles.profileEffectLayer, { width: size, height: size, opacity: Animated.multiply(glow, opacity), transform: [{ translateY }, { scale }] }, style]}><View style={[styles.adminCrownGlow, { borderColor: `${effect.color}66`, shadowColor: effect.color }]} /><View style={styles.adminCrownIcon}><Ionicons name="diamond" size={28} color={effect.color} /><Ionicons name="sparkles" size={18} color="#FFFFFF" style={styles.adminCrownSparkle} /></View></Animated.View>;
  if (effect.adminSpecial === 'aura') return <Animated.View pointerEvents="none" style={[styles.profileEffectLayer, { width: size, height: size, opacity: Animated.multiply(glow, opacity), transform: [{ scale }] }, style]}><View style={[styles.adminAuraOuter, { width: size * .82, height: size * .82, borderRadius: size, borderColor: `${effect.color}72`, shadowColor: effect.color }]} /><View style={[styles.adminAuraInner, { width: size * .62, height: size * .62, borderRadius: size, borderColor: '#64D2FF' }]} /><Ionicons name="sparkles" size={20} color="#FFFFFF" style={styles.adminAuraSparkleOne} /><Ionicons name="sparkles" size={14} color={effect.color} style={styles.adminAuraSparkleTwo} /></Animated.View>;
  return <Animated.View pointerEvents="none" style={[styles.profileEffectLayer, { width: size, height: size, opacity: Animated.multiply(glow, opacity), transform: [{ translateY }, { scale }, { rotate }] }, style]}><Image source={{ uri: effect.image }} style={styles.profileEffectImage} resizeMode="contain" /></Animated.View>;
}

function ProfileDisplayName({ person, theme, style }) {
  const effectId = person?.isAdmin ? person?.nameEffectId : null;
  const config = CEO_NAME_EFFECTS.find(x => x.id === effectId);
  const progress = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    progress.stopAnimation(); progress.setValue(0);
    if (!config) return undefined;
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(progress, { toValue: 1, duration: 1600, easing: Easing.inOut(Easing.sin), useNativeDriver: false }),
      Animated.timing(progress, { toValue: 0, duration: 1600, easing: Easing.inOut(Easing.sin), useNativeDriver: false }),
    ]));
    loop.start(); return () => loop.stop();
  }, [effectId]);
  if (!config) return <Text style={[styles.profileName, { color: theme.text }, style]}>{person?.name}</Text>;
  const color = progress.interpolate({ inputRange: [0, .5, 1], outputRange: config.colors });
  const glowOpacity = progress.interpolate({ inputRange: [0, 1], outputRange: [0.88, 1] });
  const glowColor = config.colors[1] || config.colors[0];
  return <Animated.View style={[styles.profileNameEffectWrap, { opacity: glowOpacity }]}><Animated.Text style={[styles.profileName, style, styles.profileNameEffectText, { color, textShadowColor: glowColor, textShadowRadius: 4, textShadowOffset: { width: 0, height: 0 } }]}>{person?.name}</Animated.Text></Animated.View>;
}

